WITH cleaned AS (SELECT id, last_restock, CAST(quantity AS DOUBLE) AS quantity_str, ROUND(quantity * 0.9, 2) AS quantity_adjusted FROM inventory WHERE last_restock > DATE '2023-04-25'), scored AS (SELECT *, PERCENT_RANK() OVER (PARTITION BY YEAR(last_restock) ORDER BY quantity_str) AS quantity_str_percent_rank, RANK() OVER (ORDER BY quantity_str DESC NULLS FIRST) AS quantity_str_rank FROM cleaned WHERE quantity_adjusted < 41), base AS (SELECT id, last_restock, quantity_str, quantity_adjusted, quantity_str_percent_rank, quantity_str_rank, DATE_TRUNC('MONTH', last_restock) AS last_restock_period, COALESCE(quantity_str, 0) AS quantity_str_filled FROM scored WHERE last_restock >= DATE '2023-03-31'), scored_inventory AS (SELECT id, quantity_str, quantity_str_percent_rank, last_restock_period, quantity_str_filled, SUM(quantity_str_rank) OVER (ORDER BY quantity_adjusted, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_quantity_str_rank, DENSE_RANK() OVER (ORDER BY quantity_str_filled) AS quantity_str_filled_dense_rank, ROW_NUMBER() OVER (ORDER BY quantity_adjusted, id) AS event_seq, SUM(quantity_adjusted) OVER (ORDER BY quantity_str, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_quantity_adjusted, FIRST_VALUE(quantity_adjusted) IGNORE NULLS OVER (ORDER BY quantity_str_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_quantity_adjusted FROM base), enriched AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY YEAR(last_restock_period) ORDER BY first_known_quantity_adjusted, id) AS row_seq, DENSE_RANK() OVER (ORDER BY first_known_quantity_adjusted NULLS LAST) AS first_known_quantity_adjusted_dense_rank, ROW_NUMBER() OVER (ORDER BY event_seq, id) AS event_seq_2 FROM scored_inventory), valid AS (SELECT id, quantity_str, quantity_str_percent_rank, last_restock_period, quantity_str_filled, quantity_str_filled_dense_rank, running_quantity_adjusted, row_seq, first_known_quantity_adjusted_dense_rank, event_seq_2, event_seq_2 + quantity_str_percent_rank AS event_seq_2_plus_quantity_str_percent_rank FROM enriched WHERE last_restock_period < '2024-06-01') SELECT id, quantity_str, quantity_str_percent_rank, quantity_str_filled, running_quantity_adjusted, row_seq, event_seq_2_plus_quantity_str_percent_rank FROM valid
